import csv,json,unicodedata
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922')
linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};linked.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
rs=[r for r in json.loads((P/'schmidt-poguli-siraji-remaining057.json').read_text()) if r['ID'] not in linked]
groups=[('fire', ['nār'], '125', 'aṅgāra', 'Turner125 explicitly gives Kashmiri nār fire with n from initial ṅ, rejecting derivation through Pashto from Arabic nār. Poguli nār matches this regional inherited form; the initial loss and source long vowel are retained.'), ('fire', ['agi'], '55', 'agni', 'Turner55 gives regional agg/agi fire through MIA aggi and agiṇi, with Western Pahari agg. Siraji agi fits this inherited family; the final i and unmarked initial length are preserved.'), ('sun', ['dūs', 'dīs'], '6333', 'divasa', 'Turner6333 explicitly gives Poguli and Rambani dūs sun and Ḍoḍi dīs, alongside other Pahari day/sun forms. The source Poguli dūs and Siraji dīs fit this family with its attested day-to-sun semantic range; no solar-name parent is substituted.'), ('water', ['pæ̃', 'pāṇi'], '8082', 'pānīya', 'Turner8082 explicitly gives Poguli pāĩ and neighbouring Kishtawari pāñ, Rambani pāṇi and Pahari pāṇī water. Poguli pæ̃ fits the contracted nasal-vowel type and Siraji pāṇi retains the nasal consonant; preserve both source readings and vowel quantity.'), ('star', ['tārgan'], '5798', 'tārā', 'Turner5798 section1 explicitly lists Poguli tār-gan star. This resolves the whole source response tārgan without silently stripping -gan or inventing its morphology; select the tārā branch.'), ('star', ['tārṓ'], '5798-4', 'tāraka', 'Turner5798 section4 gives neighbouring Bhadrawahi tārō and regional tāro star. Siraji tārṓ fits this final-o branch; retain its explicitly marked final stress and length.'), ('leaf', ['patiri', 'pattár'], '7733', 'pattra', 'Turner7733 includes the pattra/pattrikā leaf family, MIA pattī/pattikā and regional patrī/pattar. These support Poguli patiri with its retained r and i ending and Siraji pattár leaf; preserve the source vowel sequence and gemination rather than normalising them.')]
a=[];audit=[];source=list(csv.DictReader(open('data/other/forms/raw_data/schmidt_kashmiri.csv')));raw=list(csv.reader(open('data/other/forms/20260725-schmidt-kashmiri.csv')))
lines=['# Schmidt and Kaul: Poguli and Siraji nature vocabulary','','Ten reflex records across seven families; standing autonomous authorization. Table 3, printed pp. 287–289 and 295 (PDF pp. 57–59 and 65), visually checked.','','| # | Poguli / Siraji forms and meaning | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(g,fs,parent,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Gloss']==g and r['Form'] in fs];assert len(hits)==len(fs),(g,len(hits))
 for r in hits:
  rr=[z for z in raw if z[0]==r['Language_ID'] and z[2]==r['Original'] and z[3]==g and z[6]==r['Description']];assert len(rr)==1,(r,rr)
  item=r['Description'].split()[-1];sr=next(z for z in source if z['Item']==item)
  col={'pog':'Poguli','sir':'Siraji'}[r['Language_ID']];assert unicodedata.normalize('NFC',sr[col])==r['Original']
  page=int(sr['Page'])+230
  citation=f'schmidt[p. {page}, Table 3, item {item}];CDIAL[{parent} and addenda]'
  a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind='reflex',citation=citation,evidence=ev+' Source image and reviewed import row checked; no source transcription or identity changes.'))
  audit.append(dict(record_id=r['ID'],reviewed_source_row=sr,import_row=rr[0],printed_page=page,image=f'../tmp/pdfs/schmidt_kaul_2008/etymology/page-{sr["Page"]}.png',visual_check='confirmed'))
 label=label.replace('*',r'\*');lines.append(f'| {i} | **{" / ".join(fs)}** ‘{g}’ ({len(hits)}) | **{label}**, CDIAL **{parent}** | {ev} |')
h=[dict(record=r,reason='The source image writes a palatalised bʲ rather than a separate vowel sequence. The compiled biol spelling and its proposed bīja extension need an explicit source-profile/morphology review; no transcription or identity repair performed.') for r in rs if r['Form']=='biol' and r['Gloss']=='seed']
assert len(a)==10 and len(h)==1

for name,val in [('decisions',dict(accepted=a,held=h)),('source-audit',audit)]: (P/f'pass059-{name}.json').write_text(json.dumps(val,ensure_ascii=False,indent=2)+'\n')
lines+=['','Held: **biol** ‘seed’. The image’s palatalised b notation and the compiled spelling require further source-profile and morphological review. Other moon, cloud and seed records are outside this pass.','','Discovery: schmidt-search007–008. Full dictionary prose and separate addenda: schmidt-primary009–010. Every selected record checked against the source images and exact reviewed import row. No rebuild.','','Save and validation pending.'];(P/'pass059-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted',len(h),'held')
